VERSION = "2.37.1"

def eprint(*args, **kwargs):
    print(*args, file=sys.stderr, **kwargs)

def log_status(msg):
    # respect log_format and hide?
    # check config
    cfg = get_config()
    log_format = cfg.get("global", {}).get("log_format", "")
    # also check env
    env_fmt = os.environ.get("DIRENV_LOG_FORMAT", "")
    if env_fmt:
        log_format = env_fmt
    # Actually config log_format is read from toml; env overrides?
    # For now, if log_format == "-", disable.
    if log_format == "-":
        return
    # check log_filter regex
    log_filter = cfg.get("global", {}).get("log_filter", "")
    if log_filter:
        try:
            if re.search(log_filter, msg):
