def log_error(msg):
    cfg = get_config()
    log_format = cfg.get("global", {}).get("log_format", "")
    env_fmt = os.environ.get("DIRENV_LOG_FORMAT", "")
    if env_fmt:
        log_format = env_fmt
    if log_format == "-":
        return
    log_filter = cfg.get("global", {}).get("log_filter", "")
    if log_filter:
        try:
            if re.search(log_filter, msg):
                return
        except:
            pass
    sys.stderr.write(f"\033[31mdirenv: error {msg}\033[0m\n")
    sys.stderr.flush()

def get_config_dir():
    if "DIRENV_CONFIG" in os.environ:
        return os.environ["DIRENV_CONFIG"]
    xdg = os.environ.get("XDG_CONFIG_HOME", "")
    if xdg:
        return os.path.join(xdg, "direnv")
    home = os.environ.get("HOME", "")
    if home:
        return os.path.join(home, ".config", "direnv")
    return os.path.join(os.path.expanduser("~"), ".config", "direnv")

def get_data_dir():
    xdg = os.environ.get("XDG_DATA_HOME", "")
    if xdg:
        return os.path.join(xdg, "direnv")
    home = os.environ.get("HOME", "")
    if home:
        return os.path.join(home, ".local", "share", "direnv")
    return os.path.join(os.path.expanduser("~"), ".local", "share", "direnv")

def parse_toml_simple(path):
    # minimal TOML parser for direnv config
    data = {}
    current_section = None
    try:
        with open(path, "r") as f:
            for line in f:
                line=line.strip()
                if not line or line.startswith("#"):
                    continue
                if line.startswith("[") and line.endswith("]"):
                    sec=line[1:-1].strip()
                    current_section=sec
                    if sec not in data:
                        data[sec]={}
                    continue
                if "=" in line:
                    k,v = line.split("=",1)
                    k=k.strip()
                    v=v.strip()
                    # remove comments
                    # handle arrays, strings, bools
                    # For now, handle: string "value" or 'value', bool true/false, integer, array [...]
                    # Use simple evaluation
                    def parse_value(val):
                        val=val.strip()
                        if val.startswith('"') and val.endswith('"'):
                            # handle escapes
                            return val[1:-1].encode().decode('unicode_escape').replace('\\"', '"')
                        if val.startswith("'") and val.endswith("'"):
                            return val[1:-1]
                        if val.lower() == "true":
                            return True
                        if val.lower() == "false":
                            return False
                        if val.startswith("[") and val.endswith("]"):
                            inner=val[1:-1].strip()
                            if not inner:
                                return []
                            # split by comma not inside quotes
                            parts=[]
                            cur=""
                            in_s=False
                            in_d=False
                            for ch in inner:
                                if ch=='"' and not in_s:
                                    in_d=not in_d
                                elif ch=="'" and not in_d:
                                    in_s=not in_s
                                elif ch==',' and not in_s and not in_d:
                                    parts.append(cur.strip())
                                    cur=""
                                    continue
                                cur+=ch
                            parts.append(cur.strip())
                            res=[]
                            for p in parts:
                                if p:
                                    res.append(parse_value(p))
                            return res
                        # try integer?
                        try:
                            # check if numeric string with s suffix like 5s
                            return val
                        except:
                            return val
                    parsed = parse_value(v)
                    if current_section is None:
                        data[k]=parsed
                    else:
                        data[current_section][k]=parsed
    except FileNotFoundError:
        return {}
    return data

def get_config():
    cfg_dir = get_config_dir()
    # try direnv.toml then config.toml
    for name in ["direnv.toml", "config.toml"]:
        p = os.path.join(cfg_dir, name)
        if os.path.exists(p):
            d = parse_toml_simple(p)
            # also need to handle whitelist prefix/exact that may be string? Ensure list
            return d
    return {}

def get_self_path():
    # try to get executable path as direnv does: exec path
    try:
        # os.readlink for /proc/self/exe?
        # Use sys.argv[0] if absolute?
        p = os.path.abspath(sys.argv[0])
        # If invoked via symlink, original uses executable path? Use os.path.realpath?
        # For hook, they use whatever was used to invoke direnv, but we should use real path of executable file
        # In original, SelfPath is path to executable file (maybe via os.Executable)
        # We'll use sys.argv[0] if it contains '/', else find in PATH
        if os.path.exists(p):
            return p
        # fallback to finding executable in PATH?
        import shutil
        found = shutil.which(os.path.basename(sys.argv[0]))
        if found:
            return os.path.abspath(found)
        return p
    except:
        return sys.argv[0]

def find_rc(start_dir=None):
    if start_dir is None:
        start_dir = os.getcwd()
    cfg = get_config()
    load_dotenv = cfg.get("global", {}).get("load_dotenv", False)
    # also env var? No
    cur = os.path.abspath(start_dir)
    # Also check XDG? No
    while True:
        # check .envrc first
        envrc = os.path.join(cur, ".envrc")
        env_file = os.path.join(cur, ".env")
        found = None
        if os.path.isfile(envrc):
            found = envrc
        elif os.path.isfile(env_file):
            # if load_dotenv true, then .env is considered
            # Also if only .env exists and load_dotenv false, original still considered? Let's test: earlier with only .env and load_dotenv false, export gave "No .envrc or .env found" - so not considered unless load_dotenv true OR maybe if .env is allowed? Wait we had test with /tmp/testenv containing only .env, and export gave no RC. So with load_dotenv false, .env is ignored.
            # But with load_dotenv true, .env is considered.
            if load_dotenv:
                found = env_file
            else:
                # check if .env is allowed? Maybe need to still consider if .env is allowed via allow file? Actually we tested with load_dotenv true, after allow, .env was loaded.
                # Without load_dotenv, .env is not considered at all.
                found = None
        if found:
            return found
        # move up
        parent = os.path.dirname(cur)
        if parent == cur:
            break
        cur = parent
    return None

def expand_user(path):
    if path.startswith("~/"):
        home = os.environ.get("HOME", os.path.expanduser("~"))
        return os.path.join(home, path[2:])
    return path

def is_whitelisted(rc_path, config):
    whitelist = config.get("whitelist", {})
    prefixes = whitelist.get("prefix", [])
    exacts = whitelist.get("exact", [])
    # prefixes: list of strings
    if isinstance(prefixes, str):
        prefixes = [prefixes]
    for pref in prefixes:
        pref_exp = expand_user(pref)
        # normalize prefix: if pref is directory, check if rc_path startswith pref
        # pref may be file path? For prefix, it's prefix of rc_path
        if rc_path.startswith(pref_exp):
            # Ensure pref is directory boundary? Original checks prefix of absolute path, so "/tmp/whitelist_test" would match "/tmp/whitelist_test/sub/.envrc"
            return True
        # also if pref is like "~/code/project-b" expanded, same
    # exact
    for ex in exacts:
        ex_exp = expand_user(ex)
        # If ex is directory, treat as dir/.envrc
        # If ex_exp is directory, append /.envrc
        if os.path.isdir(ex_exp):
            ex_exp = os.path.join(ex_exp, ".envrc")
        # Otherwise, if ex doesn't end with .envrc or .env, and is directory name? The spec says if directory name passed, treat as itself with /.envrc appended
        # We should check if ex_exp corresponds to a directory path (exists as dir) then append, else check exact file match
        # For robustness, if ex_exp == rc_path, match. Also if ex_exp is directory path and rc_path == ex_exp + "/.envrc", match
        # Also need to handle that ex may be given as directory without trailing slash, but we should treat as prefix? No, exact means exact match.
        # So implement both: if rc_path == ex_exp => match
        # Also if ex_exp is a directory (without .envrc) and rc_path == ex_exp + "/.envrc" => match
        # For simplicity, check both forms
        if rc_path == ex_exp:
            return True
        # try dir form
        if rc_path == ex_exp + "/.envrc" if not ex_exp.endswith("/.envrc") else False:
            return True
        # Also if ex_exp is like "~/project-b/subdir-a" and rc_path is "/home/.../project-b/subdir-a/.envrc" ? The earlier expanded would be "/tmp/whitelist_exact/sub" vs "/tmp/whitelist_exact/sub/.envrc"
        # So check if dir without .envrc plus "/.envrc" equals rc_path
        dir_form = ex_exp
        if not dir_form.endswith(".envrc") and not dir_form.endswith(".env"):
            if rc_path == os.path.join(dir_form, ".envrc"):
                return True
    return False

def allow_file_hash(rc_path, content):
    # content is bytes or str
    if isinstance(content, str):
        content = content.encode()
    data = (rc_path + "\n").encode() + content
    return hashlib.sha256(data).hexdigest()

def deny_file_hash(rc_path):
    return hashlib.sha256((rc_path + "\n").encode()).hexdigest()

def check_allow(rc_path, config=None):
    if config is None:
        config = get_config()
    # whitelisted?
    if is_whitelisted(rc_path, config):
        return 0, None, None
    # compute hashes
    try:
        with open(rc_path, "rb") as f:
            content = f.read()
    except:
        content = b""
    allow_hash = hashlib.sha256((rc_path + "\n").encode() + content).hexdigest()
    deny_hash = hashlib.sha256((rc_path + "\n").encode()).hexdigest()
