    if start_dir is None:
        start_dir = os.getcwd()
    cfg = get_config()
    load_dotenv = cfg.get("global", {}).get("load_dotenv", False)
    # also env var? No
    cur = os.path.abspath(start_dir)
    # Also check XDG? No
    while True:
        # check .envrc first
        envrc = os.path.join(cur, ".envrc")
        env_file = os.path.join(cur, ".env")
        found = None
        if os.path.isfile(envrc):
            found = envrc
        elif os.path.isfile(env_file):
            # if load_dotenv true, then .env is considered
            # Also if only .env exists and load_dotenv false, original still considered? Let's test: earlier with only .env and load_dotenv false, export gave "No .envrc or .env found" - so not considered unless load_dotenv true OR maybe if .env is allowed? Wait we had test with /tmp/testenv containing only .env, and export gave no RC. So with load_dotenv false, .env is ignored.
            # But with load_dotenv true, .env is considered.
            if load_dotenv:
                found = env_file
            else:
                # check if .env is allowed? Maybe need to still consider if .env is allowed via allow file? Actually we tested with load_dotenv true, after allow, .env was loaded.
                # Without load_dotenv, .env is not considered at all.
                found = None
        if found:
            return found
        # move up
        parent = os.path.dirname(cur)
        if parent == cur:
            break
        cur = parent
    return None

def expand_user(path):
    if path.startswith("~/"):
        home = os.environ.get("HOME", os.path.expanduser("~"))
        return os.path.join(home, path[2:])
    return path

def is_whitelisted(rc_path, config):
    whitelist = config.get("whitelist", {})
    prefixes = whitelist.get("prefix", [])
    exacts = whitelist.get("exact", [])
    # prefixes: list of strings
    if isinstance(prefixes, str):
        prefixes = [prefixes]
    for pref in prefixes:
        pref_exp = expand_user(pref)
        # normalize prefix: if pref is directory, check if rc_path startswith pref
        # pref may be file path? For prefix, it's prefix of rc_path
        if rc_path.startswith(pref_exp):
            # Ensure pref is directory boundary? Original checks prefix of absolute path, so "/tmp/whitelist_test" would match "/tmp/whitelist_test/sub/.envrc"
            return True
        # also if pref is like "~/code/project-b" expanded, same
    # exact
    for ex in exacts:
        ex_exp = expand_user(ex)
        # If ex is directory, treat as dir/.envrc
        # If ex_exp is directory, append /.envrc
        if os.path.isdir(ex_exp):
            ex_exp = os.path.join(ex_exp, ".envrc")
        # Otherwise, if ex doesn't end with .envrc or .env, and is directory name? The spec says if directory name passed, treat as itself with /.envrc appended
        # We should check if ex_exp corresponds to a directory path (exists as dir) then append, else check exact file match
        # For robustness, if ex_exp == rc_path, match. Also if ex_exp is directory path and rc_path == ex_exp + "/.envrc", match
        # Also need to handle that ex may be given as directory without trailing slash, but we should treat as prefix? No, exact means exact match.
        # So implement both: if rc_path == ex_exp => match
        # Also if ex_exp is a directory (without .envrc) and rc_path == ex_exp + "/.envrc" => match
        # For simplicity, check both forms
        if rc_path == ex_exp:
            return True
        # try dir form
        if rc_path == ex_exp + "/.envrc" if not ex_exp.endswith("/.envrc") else False:
            return True
        # Also if ex_exp is like "~/project-b/subdir-a" and rc_path is "/home/.../project-b/subdir-a/.envrc" ? The earlier expanded would be "/tmp/whitelist_exact/sub" vs "/tmp/whitelist_exact/sub/.envrc"
        # So check if dir without .envrc plus "/.envrc" equals rc_path
        dir_form = ex_exp
        if not dir_form.endswith(".envrc") and not dir_form.endswith(".env"):
            if rc_path == os.path.join(dir_form, ".envrc"):
                return True
    return False

def allow_file_hash(rc_path, content):
    # content is bytes or str
    if isinstance(content, str):
        content = content.encode()
    data = (rc_path + "\n").encode() + content
    return hashlib.sha256(data).hexdigest()

def deny_file_hash(rc_path):
    return hashlib.sha256((rc_path + "\n").encode()).hexdigest()

def check_allow(rc_path, config=None):
    if config is None:
        config = get_config()
    # whitelisted?
    if is_whitelisted(rc_path, config):
        return 0, None, None
    # compute hashes
    try:
        with open(rc_path, "rb") as f:
            content = f.read()
    except:
        content = b""
    allow_hash = hashlib.sha256((rc_path + "\n").encode() + content).hexdigest()
    deny_hash = hashlib.sha256((rc_path + "\n").encode()).hexdigest()
    data_dir = get_data_dir()
    allow_path = os.path.join(data_dir, "allow", allow_hash)
    deny_path = os.path.join(data_dir, "deny", deny_hash)
    # check deny first?
    if os.path.exists(deny_path):
        return 2, allow_path, deny_path
    if os.path.exists(allow_path):
        return 0, allow_path, deny_path
    return 1, allow_path, deny_path

def encode_json(data):
    # json dumps with sorted keys, separators (',', ':')
    j = json.dumps(data, sort_keys=True, separators=(',', ':'))
    comp = zlib.compress(j.encode())
    enc = base64.urlsafe_b64encode(comp).decode().rstrip("=")
    return enc

def decode_json_b64(s):
    if s is None:
        return None
    # add padding
    pad = "=" * (-len(s) % 4)
    b = base64.urlsafe_b64decode(s + pad)
    dec = zlib.decompress(b)
    return json.loads(dec)

def get_watches(rc_path, allow_path, deny_path, extra=None):
    watches = []
    # rc file
    try:
        st = os.stat(rc_path)
        watches.append({"path": rc_path, "modtime": int(st.st_mtime), "exists": True})
    except:
        watches.append({"path": rc_path, "modtime": 0, "exists": False})
    # allow
    try:
        st = os.stat(allow_path)
        watches.append({"path": allow_path, "modtime": int(st.st_mtime), "exists": True})
    except:
        watches.append({"path": allow_path, "modtime": 0, "exists": False})
    # deny
    try:
        st = os.stat(deny_path)
        watches.append({"path": deny_path, "modtime": int(st.st_mtime), "exists": True})
    except:
        watches.append({"path": deny_path, "modtime": 0, "exists": False})
    if extra:
        for p in extra:
            absp = os.path.abspath(p) if not os.path.isabs(p) else p
            try:
                st = os.stat(absp)
                watches.append({"path": absp, "modtime": int(st.st_mtime), "exists": True})
            except:
                watches.append({"path": absp, "modtime": 0, "exists": False})
    return watches

def encode_watches(watches):
    j = json.dumps(watches, sort_keys=True, separators=(',', ':'))
    comp = zlib.compress(j.encode())
    enc = base64.urlsafe_b64encode(comp).decode().rstrip("=")
    return enc

def decode_watches(s):
    if not s:
        return []
    pad = "=" * (-len(s) % 4)
    b = base64.urlsafe_b64decode(s + pad)
    dec = zlib.decompress(b)
    return json.loads(dec)

def bash_quote_value(value):
    if value == "":
        return "''"
    # numeric check: pure digits and dots
    if re.fullmatch(r'[0-9]+(\.[0-9]+)*', value):
        return value
    if value == "@":
        return value
    # also handle single char safe? For now only @
    # Escape for $' ' : backslash, single quote, newline, etc.
    esc = value.replace("\\", "\\\\").replace("'", "\\'").replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t")
    # Also need to escape control chars? For now just those
    return f"$'{esc}'"

