            "DIRENV_WATCHES": watches_enc,
        }
        diff_enc = encode_json({"p": p, "n": n})
        n["DIRENV_DIFF"] = diff_enc
        exporter = SHELL_EXPORTERS[shell]
        out = exporter(p, n, watches_enc, rc_path, os.path.dirname(rc_path))
        sys.stdout.write(out)
        sys.exit(0)
    else: # allowed ==0
        # Check if already loaded and watches current -> no output
        # If DIRENV_DIR and DIRENV_FILE match current rc, and DIRENV_WATCHES matches current watches, then no change
        current_watches_enc = os.environ.get("DIRENV_WATCHES", "")
        current_dir = os.environ.get("DIRENV_DIR", "")
        current_file = os.environ.get("DIRENV_FILE", "")
        expected_dir = f"-{os.path.dirname(rc_path)}"
        if current_dir == expected_dir and current_file == rc_path and current_watches_enc == watches_enc:
            # Check if files actually not changed? We already compared enc, which includes modtimes, so if same, then no need to reload
            # But also need to ensure that file content hasn't changed without mtime change? For now treat as no output
            sys.exit(0)
        # Need to load RC via bash
        old_env = dict(os.environ)
        # Prepare to run bash
        # Get stdlib content
        stdlib_content = get_stdlib_content()
        # Write stdlib to temp?
        # Instead, we can run bash with stdlib via process substitution? Simpler to write temp file
        import tempfile
        with tempfile.NamedTemporaryFile(mode='w', delete=False, suffix='.sh') as f:
            f.write(stdlib_content)
            stdlib_path = f.name
        # Also need to handle direnvrc
        config_dir = get_config_dir()
        direnvrc_path = None
        for cand in [os.path.join(config_dir, "direnvrc"), os.path.join(os.environ.get("HOME",""), ".direnvrc")]:
            if os.path.isfile(cand):
                direnvrc_path = cand
                break
        # Build bash script to source stdlib, direnvrc, and RC, then dump
        # Use bash -c
        bash_path = config.get("global", {}).get("bash_path", "/usr/bin/bash")
        if not os.path.exists(bash_path):
            bash_path = "/bin/bash"
            if not os.path.exists(bash_path):
                bash_path = "bash"
        # Prepare env for bash subprocess
        bash_env = dict(old_env)
        bash_env["DIRENV_CONFIG"] = config_dir
        # Also set direnv var to self path
        self_path = get_self_path()
        # Write RC evaluation script
        script = f'''
        set -e
        # source stdlib
        source "{stdlib_path}"
        # source direnvrc if exists
        if [ -f "{direnvrc_path or ""}" ]; then source "{direnvrc_path or ""}"; fi
        # Now source RC
        # Use set +e for strict handling? We'll just source
        set +e
        source "{rc_path}"
        rc=$?
        if [ $rc -ne 0 ]; then
            echo "direnv: error exit status $rc" >&2
        fi
        # Dump env via python
        "{self_path}" dump json
        '''
        # Actually dump will be called via direnv dump, but we can directly call our dump
        # Run bash
        try:
            proc = subprocess.run([bash_path, "-c", script], capture_output=True, text=True, env=bash_env, cwd=os.path.dirname(rc_path))
            # proc stdout should be dump json output (env)
            # proc stderr may contain logs
            # If bash failed, we should handle
            if proc.returncode != 0 and "error" in proc.stderr:
                # RC failed
                log_error(f"exit status {proc.returncode}")
                # Still need to produce diff? Original for failtest with 'false' gave diff with no error but exit 0 and export? For failtest with 'exit 1', it gave error and diff
                # For now, produce blocked-like diff but with error
                # We'll treat as blocked?
                pass
            dump_out = proc.stdout.strip()
            # dump_out is json of new env
            try:
                new_env = json.loads(dump_out)
            except:
                # fallback to empty
                new_env = {}
            # Compute diff: p is old values for changed keys, n is new values
            p = {}
            n = {}
            # For each key in new_env that differs from old_env, add to p/n
            # Also need to handle deleted keys: if key in old_env but not in new_env, then p has old, n has null
            # But new_env includes all env vars; old_env includes all before. So we can compute.
            # Exclude some vars like _ , SHLVL, etc? Original seems to include all, but diff's p is only for changed vars, not all.
            # We should compute for all keys where old != new
            # Also need to include DIRENV_ vars in n
            # First, determine watches_enc already, and expected DIRENV_ vars
            # n should contain DIRENV_DIR, FILE, WATCHES, DIFF plus changed user vars
            # p should contain old values for those changed vars
            # Let's compute changed keys
            all_keys = set(old_env.keys()) | set(new_env.keys())
            for k in all_keys:
                old_v = old_env.get(k)
                new_v = new_env.get(k)
                if old_v != new_v:
                    # If k is DIRENV_ internal, handle separately? But we will overwrite later
                    if k.startswith("DIRENV_"):
                        continue
                    # For deleted, new_v is None
                    if k in old_env and k not in new_env:
                        p[k] = old_v
                        n[k] = None
                    elif k not in old_env and k in new_env:
                        # new var
                        # p empty for this key (don't add to p)
                        n[k] = new_v
                    else:
                        # changed
                        p[k] = old_v
                        n[k] = new_v
            # Now add DIRENV_ vars to n
            n["DIRENV_DIR"] = f"-{os.path.dirname(rc_path)}"
            n["DIRENV_FILE"] = rc_path
            n["DIRENV_WATCHES"] = watches_enc
            # For p, if DIRENV_ vars were previously set, they would be in old_env, but we want p to be {} for first load? In earlier diffs, p was {} for first load, even though old_env had PATH etc. But for PATH case, p had old PATH. So p for DIRENV_ should be {}? Actually for first load, p was {}, not containing old DIRENV_ values (since they were not set before). For reload, p would contain previous n?
            # Our p currently contains old PATH if changed, which matches earlier.
            # For DIRENV_ themselves, p should remain {} for first load, but for unload, p will be previous n's values?
            # For now, keep p as computed (which may not include DIRENV_).
            # But we need to ensure p does not contain DIRENV_ for first load
            # Remove DIRENV_ from p if present
            for k in list(p.keys()):
                if k.startswith("DIRENV_"):
                    del p[k]
            # Encode diff
            diff_enc = encode_json({"p": p, "n": n})
            n["DIRENV_DIFF"] = diff_enc
            # Also need to handle hide_env_diff: if true, don't log export +VAR?
            hide = config.get("global", {}).get("hide_env_diff", False)
            exporter = SHELL_EXPORTERS[shell]
            out = exporter(p, n, watches_enc, rc_path, os.path.dirname(rc_path))
            # Logging
            if not hide:
                # Log loading and export
                log_status(f"loading {rc_path}")
                # For each new var in n that is not DIRENV_, log export +VAR or ~VAR
                for k in sorted(n.keys()):
                    if k.startswith("DIRENV_"):
                        continue
                    if n[k] is None:
                        log_status(f"unloading {k}")
                    else:
                        if k in p:
                            log_status(f"export ~{k}")
                        else:
                            log_status(f"export +{k}")
                # Also handle PATH etc. ~ indicates changed
            else:
                log_status(f"loading {rc_path}")
            sys.stdout.write(out)
            # Forward stderr from bash (like errors) to our stderr
            if proc.stderr:
                sys.stderr.write(proc.stderr)
            sys.exit(0)
        except Exception as e:
            log_error(f"failed to load {rc_path}: {e}")
            sys.exit(1)
        finally:
            try:
                os.unlink(stdlib_path)
            except:
                pass

def get_stdlib_content():
    # Return stdlib.sh content. Try to read from embedded file or from original location
    # For now, try to read from __file__ dir
    try:
        # Look for stdlib file next to this script
        base = os.path.dirname(os.path.abspath(__file__))
        for cand in [os.path.join(base, "stdlib.sh"), "/tmp/stdlib.sh", "./stdlib_embed.sh"]:
            if os.path.exists(cand):
                with open(cand, "r") as f:
                    return f.read()
    except:
        pass
    # Fallback minimal stdlib (just defines has etc.)
    return '''
direnv="''' + get_self_path() + '''"
has() { type "$1" &>/dev/null; }
expand_path() { realpath "$1"; }
'''

def cmd_allow(args):
    # allow [PATH_TO_RC]
    path = None
    if len(args) >= 1:
        path = args[0]
    else:
        # find RC in current dir
        rc = find_rc()
        if not rc:
            log_error(".envrc not found")
            sys.exit(1)
        path = rc
    # Resolve to absolute
    if not os.path.isabs(path):
        path = os.path.abspath(path)
    # If path is directory, append .envrc
    if os.path.isdir(path):
        # check for .envrc then .env
        cand1 = os.path.join(path, ".envrc")
        cand2 = os.path.join(path, ".env")
        if os.path.isfile(cand1):
            path = cand1
        elif os.path.isfile(cand2):
            path = cand2
        else:
            log_error(".envrc not found")
            sys.exit(1)
    # Check file exists
    if not os.path.isfile(path):
        log_error(f"lstat {path}: no such file or directory")
        sys.exit(1)
    # Compute hash
    with open(path, "rb") as f:
        content = f.read()
    h = hashlib.sha256((path + "\n").encode() + content).hexdigest()
    data_dir = get_data_dir()
    allow_dir = os.path.join(data_dir, "allow")
    os.makedirs(allow_dir, exist_ok=True)
    allow_path = os.path.join(allow_dir, h)
    # Write file
    with open(allow_path, "w") as f:
        f.write(path + "\n")
    # Remove deny if exists
    deny_hash = hashlib.sha256((path + "\n").encode()).hexdigest()
    deny_path = os.path.join(data_dir, "deny", deny_hash)
    if os.path.exists(deny_path):
        try:
            os.unlink(deny_path)
        except:
            pass
    sys.exit(0)

def cmd_deny(args):
    # deny/block
    path = None
    if len(args) >= 1:
        path = args[0]
    else:
        rc = find_rc()
        if not rc:
            log_error(".envrc not found")
            sys.exit(1)
        path = rc
    if not os.path.isabs(path):
        path = os.path.abspath(path)
    if os.path.isdir(path):
        cand1 = os.path.join(path, ".envrc")
        cand2 = os.path.join(path, ".env")
        if os.path.isfile(cand1):
            path = cand1
        elif os.path.isfile(cand2):
            path = cand2
        else:
            log_error(".envrc not found")
            sys.exit(1)
    if not os.path.isfile(path):
        log_error(f"lstat {path}: no such file or directory")
        sys.exit(1)
    data_dir = get_data_dir()
    deny_hash = hashlib.sha256((path + "\n").encode()).hexdigest()
    deny_dir = os.path.join(data_dir, "deny")
    os.makedirs(deny_dir, exist_ok=True)
    deny_path = os.path.join(deny_dir, deny_hash)
    with open(deny_path, "w") as f:
        f.write(path + "\n")
    # Remove all allow files for this path (any hash that contains same path? The allow files are hashed with content, so there may be multiple for same path with different contents)
    # Remove any allow file that contains path string
    allow_dir = os.path.join(data_dir, "allow")
    if os.path.isdir(allow_dir):
        for fname in os.listdir(allow_dir):
            fpath = os.path.join(allow_dir, fname)
            try:
                with open(fpath, "r") as f:
                    c = f.read().strip()
                if c == path:
                    os.unlink(fpath)
            except:
                pass
    sys.exit(0)

def cmd_prune(args):
    data_dir = get_data_dir()
    allow_dir = os.path.join(data_dir, "allow")
    if os.path.isdir(allow_dir):
        for fname in os.listdir(allow_dir):
            fpath = os.path.join(allow_dir, fname)
            try:
                with open(fpath, "r") as f:
                    rc_path = f.read().strip()
                # check if file still exists and hash matches
                if not os.path.isfile(rc_path):
                    os.unlink(fpath)
                    continue
                with open(rc_path, "rb") as rf:
                    content = rf.read()
                expected = hashlib.sha256((rc_path + "\n").encode() + content).hexdigest()
                if fname != expected:
                    os.unlink(fpath)
            except:
                pass
    # Also prune deny? Original prune removes old allowed and required files - for now just allow
    sys.exit(0)

