    desired = ver
    # Validate semver: should be like x.y.z optionally with prerelease?
    if not re.fullmatch(r'[0-9]+\.[0-9]+\.[0-9]+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?', desired) and not re.fullmatch(r'[0-9]+\.[0-9]+', desired) and not re.fullmatch(r'[0-9]+', desired):
        # Try to parse as semver, if fails, error
        log_error(f"{args[0]} is not a valid semver version")
        sys.exit(1)
    # Compare versions
    def parse(v):
        v = v.lstrip("v")
        # split by .
        parts = re.split(r'[.-]', v)
        nums = []
        for p in parts:
            try:
                nums.append(int(p))
            except:
                nums.append(p)
        return nums
    cur = parse(VERSION)
    des = parse(desired)
    # Compare numeric parts
    for i in range(max(len(cur), len(des))):
        a = cur[i] if i < len(cur) else 0
        b = des[i] if i < len(des) else 0
        if isinstance(a, int) and isinstance(b, int):
            if a < b:
                log_error(f"current version v{VERSION} is older than the desired version v{desired}")
                sys.exit(1)
            elif a > b:
                break
        else:
            # string compare
            if str(a) < str(b):
                log_error(f"current version v{VERSION} is older than the desired version v{desired}")
                sys.exit(1)
            elif str(a) > str(b):
                break
    sys.exit(0)

