def cmd_exec(args):
    if len(args) < 2:
        log_error("invalid arguments")
        sys.exit(1)
    dir_path = args[0]
    cmd = args[1:]
    # Find RC in dir_path
    rc_path = find_rc(start_dir=dir_path)
    if rc_path:
        config = get_config()
        allowed, _, _ = check_allow(rc_path, config)
        if allowed != 0:
            # If blocked, error
            if allowed == 1:
                log_error(f"{rc_path} is blocked. Run `direnv allow` to approve its content")
                sys.exit(1)
            elif allowed == 2:
                # denied, but exec should still load? For denied, original exec perhaps not load? Let's see: after deny, exec should still fail? For scen5 denied, exec was not tested. For now, treat denied as not loading but still exec without env?
                pass
        else:
            # Load RC and set env for command
            # For simplicity, run export and eval
            # Use our export logic to get env, then run command with that env
            # Instead, we can run bash to load RC and then exec command
            # Use subprocess with env after loading
            old_env = dict(os.environ)
            # Simulate loading RC via our export logic but directly via bash
            # For now, just run command with env after sourcing RC
            bash_path = config.get("global", {}).get("bash_path", "/usr/bin/bash")
            if not os.path.exists(bash_path):
                bash_path = "bash"
            # Build command that sources RC and then execs
            # Use direnv export?
            # Simpler: Run bash that sources stdlib and RC, then execs cmd
            stdlib_content = get_stdlib_content()
            import tempfile
            with tempfile.NamedTemporaryFile(mode='w', delete=False, suffix='.sh') as f:
                f.write(stdlib_content)
                stdlib_path = f.name
            config_dir = get_config_dir()
            direnvrc_path = None
            for cand in [os.path.join(config_dir, "direnvrc"), os.path.join(os.environ.get("HOME",""), ".direnvrc")]:
                if os.path.isfile(cand):
                    direnvrc_path = cand
                    break
            self_path = get_self_path()
            # Build script
            script = f'''
            source "{stdlib_path}"
            if [ -f "{direnvrc_path or ""}" ]; then source "{direnvrc_path or ""}"; fi
            source "{rc_path}"
            exec {" ".join(shlex.quote(c) for c in cmd)}
            '''
            try:
                proc = subprocess.run([bash_path, "-c", script], env=old_env)
                sys.exit(proc.returncode)
            finally:
                try:
                    os.unlink(stdlib_path)
                except:
                    pass
    # No RC or not allowed: just exec without loading
    # If no RC, just exec command directly
    try:
        proc = subprocess.run(cmd)
        sys.exit(proc.returncode)
    except FileNotFoundError:
        log_error(f"executing {cmd[0]}: no such file or directory")
        sys.exit(1)

