    if not os.path.isabs(path):
        path = os.path.abspath(path)
    if os.path.isdir(path):
        # if directory, look for .envrc
        cand = os.path.join(path, ".envrc")
        if os.path.isfile(cand):
            path = cand
        else:
            cand2 = os.path.join(path, ".env")
            if os.path.isfile(cand2):
                path = cand2
            else:
                path = cand
    editor = os.environ.get("EDITOR", os.environ.get("VISUAL", "vi"))
    # If path doesn't exist, create empty
    if not os.path.exists(path):
        open(path, "a").close()
    # Get mtime before
    try:
        before = os.stat(path).st_mtime
    except:
        before = 0
    # Run editor
    try:
        subprocess.run([editor, path])
    except:
        # fallback to true
        pass
    try:
        after = os.stat(path).st_mtime
    except:
        after = before
    if after != before:
        # allow
        with open(path, "rb") as f:
            content = f.read()
        h = hashlib.sha256((path + "\n").encode() + content).hexdigest()
        data_dir = get_data_dir()
        allow_dir = os.path.join(data_dir, "allow")
        os.makedirs(allow_dir, exist_ok=True)
        allow_path = os.path.join(allow_dir, h)
