            f.write(path + "\n")
    sys.exit(0)

def cmd_fetchurl(args):
    if len(args) < 1:
        log_error("missing url argument")
        sys.exit(1)
    url = args[0]
    # Try to fetch via urllib
    import urllib.request, urllib.error
    try:
        # Simple fetch with timeout 5s
        with urllib.request.urlopen(url, timeout=5) as resp:
            data = resp.read()
            # Store in cache? For now just print path?
            # Original stores in CAS and outputs path
            # We'll just output to stdout a fake path
            # But need to handle integrity hash if provided
            if len(args) >= 2:
                expected = args[1]
                # Check hash: expected is like sha256-... ?
                # For now just compute sha256 of data and compare
                h = hashlib.sha256(data).hexdigest()
                # If expected contains '-', split?
                # Original uses SRI hash like sha256- base64
                # We'll just compare if expected in h
                if expected not in h:
