def cmd_dotenv(args):
    # dotenv [SHELL] [PATH_TO_DOTENV]
    # Transforms .env file to export statements
    shell = "bash"
    path = ".env"
    if len(args) >= 1:
        if args[0] in SHELL_EXPORTERS:
            shell = args[0]
            if len(args) >= 2:
                path = args[1]
        else:
            path = args[0]
    if not os.path.isabs(path):
        path = os.path.join(os.getcwd(), path)
    if not os.path.isfile(path):
        log_error(f"open {path}: no such file or directory")
        sys.exit(1)
    # Parse .env file: lines of KEY=VALUE, ignoring comments, handling quotes
    exports = {}
    with open(path, "r") as f:
        for line in f:
            line=line.strip()
            if not line or line.startswith("#"):
                continue
            if "=" not in line:
                continue
            k,v = line.split("=",1)
            k=k.strip()
            v=v.strip()
            # Remove surrounding quotes
            if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
                v=v[1:-1]
                # handle escapes? For double quoted, \n etc.
                v=v.encode().decode('unicode_escape')
            exports[k]=v
    # Output for shell
    if shell == "bash" or shell == "zsh":
        parts=[]
        for k,v in exports.items():
            q = bash_quote_value(v)
            parts.append(f"export {k}={q};")
        sys.stdout.write("".join(parts))
    elif shell == "fish":
        parts=[]
        for k,v in exports.items():
            esc = v.replace("'", "\\'")
            parts.append(f"set -x -g '{k}' '{esc}';")
        sys.stdout.write("".join(parts))
    elif shell == "json":
        json.dump(exports, sys.stdout, sort_keys=True)
    else:
        # generic
        for k,v in exports.items():
            sys.stdout.write(f"{k}={v}\n")
    sys.exit(0)

def cmd_watch(args):
