        sys.stdout.write(f"export DIRENV_WATCHES=$'{new_enc}';")
    elif shell == "fish":
        sys.stdout.write(f"set -x -g 'DIRENV_WATCHES' '{new_enc}';")
    else:
        sys.stdout.write(new_enc)
    sys.exit(0)

