            dp = os.path.join(root, d)
            try:
                st = os.stat(dp)
                watches.append({"path": dp, "modtime": int(st.st_mtime), "exists": True})
            except:
                watches.append({"path": dp, "modtime": 0, "exists": False})
    new_enc = encode_watches(watches)
    if shell == "bash" or shell == "zsh":
        sys.stdout.write(f"export DIRENV_WATCHES=$'{new_enc}';")
    elif shell == "fish":
